# 입력된 이름의 공백을 정리하고 제목 형식으로 바꿉니다.
def normalize_name(name):
    cleaned = name.strip()
    return cleaned.title()

print(normalize_name("  ada lovelace  "))

# 0으로 나누는 상황을 피하고 기본값을 반환합니다.
def safe_divide(left, right, default=0):
    if right == 0:
        return default
    return left / right

print(safe_divide(10, 2))

# 숫자가 최소값과 최대값 사이에 머물도록 제한합니다.
def clamp(value, minimum, maximum):
    lower_bound = max(value, minimum)
    return min(lower_bound, maximum)

volume = clamp(120, 0, 100)
print(volume)

# 숫자 목록이 비어 있어도 안전하게 평균을 계산합니다.
def average(values):
    if not values:
        return 0
    return sum(values) / len(values)

print(average([80, 90, 100]))

# 점수 목록에서 평균과 최고 점수를 함께 요약합니다.
def summarize_scores(scores):
    return {
        "average": sum(scores) / len(scores),
        "highest": max(scores),
    }

print(summarize_scores([72, 88, 95]))

# 문장에 나온 각 단어의 횟수를 사전으로 계산합니다.
def count_words(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

print(count_words("code more code"))

# 처음 등장한 순서를 유지하면서 중복 값을 제거합니다.
def unique_items(items):
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result

print(unique_items([1, 2, 1, 3]))

# 목록에서 두 번 이상 나온 값만 찾아 반환합니다.
def find_duplicates(items):
    seen = set()
    duplicates = set()
    for item in items:
        if item in seen:
            duplicates.add(item)
            continue
        seen.add(item)
    return sorted(duplicates)

# 중첩된 사전에서 키 경로를 따라 값을 안전하게 찾습니다.
def get_nested(data, keys, default=None):
    current = data
    for key in keys:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current

# 파일 이름을 확장자별 목록으로 묶어 정리합니다.
def group_by_extension(files):
    groups = {}
    for filename in files:
        extension = filename.rsplit(".", 1)[-1]
        groups.setdefault(extension, []).append(filename)
    return groups

print(group_by_extension(["a.py", "b.txt", "c.py"]))

# 경로에서 마지막 파일의 확장자만 소문자로 가져옵니다.
def file_extension(path):
    filename = path.rsplit("/", 1)[-1]
    if "." not in filename:
        return ""
    return filename.rsplit(".", 1)[-1].lower()

print(file_extension("reports/SALES.CSV"))

# 제목의 공백과 특수 문자를 정리해 파일 이름을 만듭니다.
def safe_filename(title):
    allowed = []
    for char in title.strip().lower():
        allowed.append(char if char.isalnum() else "-")
    return "".join(allowed).strip("-")

print(safe_filename("Monthly Report 2026"))

# 게시글 제목을 URL에 사용할 수 있는 짧은 문자열로 바꿉니다.
def make_slug(title):
    words = title.strip().lower().split()
    safe_words = [word.strip(".,!?") for word in words]
    return "-".join(word for word in safe_words if word)

print(make_slug("Python API Guide!"))

# 검색 조건 사전을 URL 쿼리 문자열로 변환합니다.
def build_query(params):
    pairs = []
    for key, value in sorted(params.items()):
        pairs.append(f"{key}={value}")
    return "&".join(pairs)

print(build_query({"page": 2, "sort": "new"}))

# 문자열 설정값을 True 또는 False로 변환합니다.
def parse_bool(value):
    normalized = value.strip().lower()
    if normalized in {"true", "1", "yes", "on"}:
        return True
    if normalized in {"false", "0", "no", "off"}:
        return False
    raise ValueError("invalid boolean")

# 환경 변수에 값이 없으면 안전한 기본 설정을 사용합니다.
import os

def get_port():
    raw_port = os.getenv("APP_PORT", "8000")
    return int(raw_port)

print(get_port())

# 재시도 횟수에 따라 대기 시간을 두 배씩 늘립니다.
def retry_delay(attempt, base=0.5, maximum=8):
    delay = base * (2 ** attempt)
    return min(delay, maximum)

for attempt in range(4):
    print(retry_delay(attempt))

# 많은 작업을 일정한 크기의 배치로 순서대로 꺼냅니다.
def batches(tasks, size):
    for start in range(0, len(tasks), size):
        yield tasks[start:start + size]

tasks = ["a", "b", "c", "d", "e"]
for batch in batches(tasks, 2):
    print(batch)

# 원래 가격에 할인율을 적용하고 0원 아래로 내려가지 않게 합니다.
def discounted_price(price, percent):
    rate = max(0, min(percent, 100)) / 100
    discounted = price * (1 - rate)
    return round(discounted)

print(discounted_price(25000, 20))

# 공급가에 세율을 적용해 세금 포함 금액을 계산합니다.
def price_with_tax(price, tax_rate=0.1):
    tax = price * tax_rate
    total = price + tax
    return round(total)

print(price_with_tax(10000))

# 사용자 목록에서 활성 상태인 사용자 이름만 추출합니다.
def active_user_names(users):
    names = []
    for user in users:
        if user.get("active"):
            names.append(user["name"])
    return names

users = [{"name": "Ada", "active": True}, {"name": "Lin", "active": False}]
print(active_user_names(users))

# 사전 목록을 점수는 높은 순서, 이름은 가나다순으로 정렬합니다.
def sort_records(records):
    return sorted(
        records,
        key=lambda item: (-item["score"], item["name"]),
    )

records = [{"name": "Kim", "score": 80}, {"name": "Lee", "score": 95}]
print(sort_records(records))

# 레코드 목록을 ID로 빠르게 찾을 수 있는 사전으로 바꿉니다.
def index_by_id(records):
    index = {}
    for record in records:
        index[record["id"]] = record
    return index

records = [{"id": 101, "name": "Ada"}, {"id": 102, "name": "Lin"}]
print(index_by_id(records)[102])

# 섭씨 온도를 화씨 온도로 변환하고 한 자리까지 반올림합니다.
def celsius_to_fahrenheit(celsius):
    fahrenheit = celsius * 9 / 5 + 32
    return round(fahrenheit, 1)

print(celsius_to_fahrenheit(25))

# 킬로미터를 마일로 변환하고 두 자리까지 반올림합니다.
def kilometers_to_miles(kilometers):
    miles = kilometers * 0.621371
    return round(miles, 2)

print(kilometers_to_miles(10))

# 이미 계산한 값은 사전에 저장해 다음 호출에서 재사용합니다.
cache = {}

def square_cached(number):
    if number not in cache:
        cache[number] = number * number
    return cache[number]

print(square_cached(12))

# 함수 결과를 인자별로 저장하는 간단한 장식자를 만듭니다.
def memoize(function):
    cache = {}
    def wrapper(value):
        if value not in cache:
            cache[value] = function(value)
        return cache[value]
    return wrapper

@memoize
def double(number):
    return number * 2

# HTTP 상태 코드의 범위에 따라 결과 종류를 분류합니다.
def status_family(status):
    if 200 <= status < 300:
        return "success"
    if 400 <= status < 500:
        return "client_error"
    if 500 <= status < 600:
        return "server_error"
    return "other"

# 메뉴 번호를 받아 실행할 작업 이름을 안전하게 선택합니다.
def choose_action(choice):
    actions = {"1": "create", "2": "list", "3": "exit"}
    action = actions.get(choice)
    if action is None:
        return "invalid"
    return action

print(choose_action("2"))
